9	const runtimeEnv = ((import.meta as ImportMeta & { env?: RuntimeEnv }).env ?? {});
10	const SYSTEM_HOST = window.location.hostname || '127.0.0.1';
11	const HTTP_PROTOCOL = window.location.protocol === 'https:' ? 'https:' : 'http:';
12	const WS_PROTOCOL = HTTP_PROTOCOL === 'https:' ? 'wss:' : 'ws:';
13	const PRIMARY_PORT = runtimeEnv.VITE_API_PORT?.trim() || '3004';
14	const CONFIGURED_API_ORIGIN = runtimeEnv.VITE_API_ORIGIN?.trim();
15	const AUTH_HEADER_NAME = 'X-API-KEY';
16	const AUTH_STORAGE_KEY = 'nudimmud.runtime-api-key';
