18	
19	let runtimeAuthToken: string | null | undefined;
20	let runtimeAuthTokenPromise: Promise<string | null> | null = null;
21	
22	function buildOrigin(protocol: string, port: string) {
23	    return `${protocol}//${SYSTEM_HOST}:${port}`;
24	}
25	
26	function normalizePath(pathOrUrl: string) {
27	    try {
28	        const parsed = new URL(pathOrUrl, buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT));
29	        return `${parsed.pathname}${parsed.search}`;
30	    } catch {
31	        return pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
32	    }
33	}
34	
35	function dedupe(values: string[]) {
36	    return [...new Set(values.filter(Boolean))];
37	}
38	
39	function parsePortList(value?: string) {
40	    return (value || '')
41	        .split(',')
42	        .map((port) => port.trim())
43	        .filter(Boolean);
44	}
45	
46	const FALLBACK_PORTS = dedupe([
47	    ...parsePortList(runtimeEnv.VITE_API_FALLBACK_PORTS),
48	    runtimeEnv.VITE_API_FALLBACK_PORT?.trim() || '',
49	    '3005',
50	    '3003'
51	]);
52	
53	export const API_ORIGINS = dedupe([
54	    CONFIGURED_API_ORIGIN || buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT),
55	    ...(CONFIGURED_API_ORIGIN ? [] : FALLBACK_PORTS.map((port) => buildOrigin(HTTP_PROTOCOL, port)))
56	]);
57	
58	export const WS_ORIGINS = API_ORIGINS.map((origin) =>
59	    origin.replace(/^https?:/, WS_PROTOCOL)
60	);
61	
62	export function apiUrl(pathOrUrl: string, origin = API_ORIGINS[0]) {
63	    return `${origin}${normalizePath(pathOrUrl)}`;
64	}
65	
66	function readStoredAuthToken() {
67	    try {
68	        return window.sessionStorage.getItem(AUTH_STORAGE_KEY)?.trim() || null;
69	    } catch {
70	        return null;
71	    }
72	}
73	
74	function storeAuthToken(token: string | null) {
75	    runtimeAuthToken = token;
76	    try {
77	        if (token) {
78	            window.sessionStorage.setItem(AUTH_STORAGE_KEY, token);
79	        } else {
80	            window.sessionStorage.removeItem(AUTH_STORAGE_KEY);
81	        }
82	    } catch {
83	        // Session storage is best-effort only.
84	    }
85	}
86	
87	function extractBootstrapToken(response: Response, payload: unknown) {
88	    const headerToken = response.headers.get(AUTH_HEADER_NAME) || response.headers.get(AUTH_HEADER_NAME.toLowerCase());
89	    if (headerToken?.trim()) return headerToken.trim();
90	
91	    if (typeof payload === 'string') {
92	        const trimmed = payload.trim();
93	        return trimmed || null;
94	    }
95	
96	    if (!payload || typeof payload !== 'object') return null;
97	
98	    const candidate = (payload as Record<string, unknown>).apiKey
99	        || (payload as Record<string, unknown>).api_key
100	        || (payload as Record<string, unknown>).token
101	        || (payload as Record<string, unknown>).authToken
102	        || (payload as Record<string, unknown>).value
103	        || (payload as Record<string, unknown>).key;
104	
105	    return typeof candidate === 'string' && candidate.trim() ? candidate.trim() : null;
106	}
