108	async function fetchFromOrigin(pathOrUrl: string, origin: string, init?: RequestInit) {
109	    return fetch(apiUrl(pathOrUrl, origin), init);
110	}
111	
112	async function fetchRuntimeBootstrapToken(origin: string) {
113	    try {
114	        const response = await fetchFromOrigin(BOOTSTRAP_PATH, origin, { credentials: 'same-origin' });
115	        if (!response.ok) return null;
116	
117	        const raw = await response.text().catch(() => '');
118	        try {
119	            return extractBootstrapToken(response, JSON.parse(raw));
120	        } catch {
121	            return extractBootstrapToken(response, raw);
122	        }
123	    } catch {
124	        return null;
125	    }
126	}
127	
128	async function resolveRuntimeAuthToken() {
129	    if (runtimeAuthToken !== undefined) {
130	        return runtimeAuthToken;
131	    }
132	
133	    const storedToken = readStoredAuthToken();
134	    if (storedToken) {
135	        runtimeAuthToken = storedToken;
136	        return storedToken;
137	    }
138	
139	    runtimeAuthTokenPromise ||= (async () => {
140	        for (const origin of API_ORIGINS) {
141	            const token = await fetchRuntimeBootstrapToken(origin);
142	            if (token) return token;
143	        }
144	        return null;
145	    })();
146	
147	    const token = await runtimeAuthTokenPromise;
148	    runtimeAuthTokenPromise = null;
149	    if (token) {
150	        storeAuthToken(token);
151	        return token;
152	    }
153	
154	    storeAuthToken(null);
155	    return null;
156	}
157	
158	function withAuthHeader(init: RequestInit | undefined, token: string | null) {
159	    const headers = new Headers(init?.headers || {});
160	    if (token && !headers.has(AUTH_HEADER_NAME)) {
161	        headers.set(AUTH_HEADER_NAME, token);
162	    }
163	    return {
164	        ...(init || {}),
165	        headers
166	    };
167	}
