255	class NexusConstellation {
256	    canvas: HTMLCanvasElement;
257	    ctx: CanvasRenderingContext2D;
258	    nodes: any[] = [];
259	    offset = { x: 0, y: 0 };
260	    scale = 1;
261	    dragging = false;
262	    last = { x: 0, y: 0 };
263	
264	    constructor(canvasId: string) {
265	        this.canvas = document.getElementById(canvasId) as HTMLCanvasElement;
266	        this.ctx = this.canvas.getContext('2d')!;
267	        this.resize();
268	        window.addEventListener('resize', () => this.resize());
269	        this.offset = { x: this.canvas.width / 2, y: this.canvas.height / 2 };
270	        
271	        let dragStartX = 0;
272	        let dragStartY = 0;
273	
274	        this.canvas.addEventListener('mousedown', e => { 
275	            this.dragging = true; 
276	            this.last = { x: e.clientX, y: e.clientY }; 
277	            dragStartX = e.clientX;
278	            dragStartY = e.clientY;
279	        });
280	
281	        window.addEventListener('mousemove', e => {
282	            if (!this.dragging) return;
283	            this.offset.x += e.clientX - this.last.x;
284	            this.offset.y += e.clientY - this.last.y;
285	            this.last = { x: e.clientX, y: e.clientY };
286	        });
287	
288	        window.addEventListener('mouseup', e => { 
289	            this.dragging = false; 
290	            const dx = Math.abs(e.clientX - dragStartX);
291	            const dy = Math.abs(e.clientY - dragStartY);
292	            
293	            // If it was a click (not a drag), try to open a node
294	            if (dx < 5 && dy < 5) {
295	                this.handleNodeClick(e.clientX, e.clientY);
296	            }
297	        });
298	
299	        this.canvas.addEventListener('wheel', e => {
300	            e.preventDefault();
301	            this.scale *= e.deltaY < 0 ? 1.05 : 0.95;
302	            this.scale = Math.min(Math.max(0.1, this.scale), 5);
303	        }, { passive: false });
304	        
305	        this.seedNodes();
306	        this.loadKnowledge();
307	        this.draw();
308	    }
